\title{\bfseries Rank Correlation as Chordal Distance on the Permutohedron:\\
Quantisation, Metric Equivalence, and a Structural Ceiling\\ for Thresholded Statistics}
\author{Aristotle}
\date{4 September 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop the finite geometry of Spearman's rank correlation. On a tie-free population of $n$ items a ranking is a vertex of the permutohedron $\Pi_{n-1}\subset\mathbb{R}^n$, and Spearman's statistic $\sum d^2$ is the squared Euclidean distance between two such vertices. Because all $n!$ vertices lie on a single sphere inside a single hyperplane, $\sum d^2$ is an affine function of the inner product of the rank vectors; we show that the classical normalisation $\rho = 1 - 6\sum d^2/(n^3-n)$ is exactly the Pearson correlation coefficient of the rank vectors. From this vantage point we obtain: (i) a quantisation theorem---$\sum d^2$ is always even, hence distinct rankings satisfy $\sum d^2\ge 2$ and no attainable value of $\rho$ lies in the open interval $(1-12/(n^3-n),\,1)$---together with the exact diameter $\max\sum d^2 = n(n^2-1)/3$, realised only by the reversal; (ii) exact unbiasedness, $\sum_{\sigma\in \Sn}\rho(\sigma,\id)=0$ and $\mathbb{E}[\sum d^2]=(n^3-n)/6$, from position-blindness of the uniform ensemble; (iii) equivalence of the $\ell^1$, $\ell^2$ and pairwise-disorder readings, via $F\le \sum d^2\le (n-1)F$, $F^2\le n\sum d^2$, and the Diaconis--Graham upper bound $F(\sigma)\le 2\inv(\sigma)$ with the constant $2$ sharp; and (iv) a sharp ceiling for thresholded statistics: coarsening by a threshold that flags $m$ of $n$ items caps the squared correlation with any ranking at $3m(n-m)/(n^2-1)\approx 3p(1-p)$, independently of the statistic. At a $10\%$ flag rate this caps $|r|$ at $0.520$, which gives a structural---not statistical---explanation for the systematic failure of correlation acceptance bands under threshold tightening.
\end{abstract}

\section{Introduction}

\subsection{Motivation}

A recurrent pattern in the monitoring of large systems is the \emph{dial}: a scalar statistic $T$ is computed per item, an outcome rate is observed, and the health of the system is summarised by the rank correlation between the two. An acceptance band is fixed in advance; readings inside it are ``in regime''. Downstream, however, the statistic is rarely used continuously: an operating threshold $u$ converts it into a binary flag.

Such a dial has two independent axes of validation. Along the \emph{population axis} one asks whether the reading is stable as the population size $N$ varies over orders of magnitude. Along the \emph{threshold axis} one asks whether the reading survives a change in the operating point $u$.

Empirical calibration exhibits a striking asymmetry between the two. Across five independent populations with $N$ spanning $2^{27}$ to $2^{38}$ the reading remained inside a band $[0.71,\,0.76]$ on all five, with mean $0.713$ against an anchor of $0.717$: the population axis is inert. Moving the operating point from $u=2.5$ to $u=3.5$, in contrast, degraded \emph{every} population (a sign test on $5/5$, $p\approx 0.03$), with the worst reading collapsing to $0.487$ and the mean falling below the band floor. The degradation is systematic, not noisy.

This paper argues that both halves of that asymmetry are consequences of finite geometry, and that the second in particular is not a statistical phenomenon at all but a hard ceiling imposed by the shape of the space of rankings.

\subsection{The change of viewpoint}

A tie-free ranking of $n$ items assigns each item a distinct value in $\{0,\dots,n-1\}$, so it is a permutation $\sigma\in \Sn$, and its \emph{rank vector} $(\sigma(0),\dots,\sigma(n-1))\in\mathbb{Z}^n$ is a point in Euclidean space. The convex hull of the $n!$ rank vectors is the \emph{permutohedron} $\Pi_{n-1}$, an $(n-1)$-dimensional polytope whose vertices are exactly those points: a hexagon for $n=3$, a truncated octahedron for $n=4$. Spearman's raw statistic $\sum_i d_i^2$ is then literally the squared Euclidean distance between two vertices, and every property of the dial becomes a property of a finite point configuration.

\section{Setup: rank vectors and cosphericity}

Throughout $n\ge 2$ and $\Sn$ is the group of permutations of $\{0,1,\dots,n-1\}$.

\begin{definition}[Rank vector]
For $\sigma\in \Sn$ the \emph{rank vector} is $\rk\sigma = (\sigma(0),\dots,\sigma(n-1))\in\mathbb{Z}^n$.
\end{definition}

\begin{definition}[Structure constants]
$L(n) := \sum_{i=0}^{n-1} i$ and $R(n) := \sum_{i=0}^{n-1} i^2$.
\end{definition}

\begin{definition}[The statistics]
For $\sigma,\tau\in \Sn$,
\[
D(\sigma,\tau) := \sum_i\bigl(\sigma(i)-\tau(i)\bigr)^2,\qquad
\langle\sigma,\tau\rangle := \sum_i \sigma(i)\tau(i),\qquad
\rho(\sigma,\tau) := 1-\frac{6D(\sigma,\tau)}{n^3-n}.
\]
\end{definition}

\begin{theorem}[Cosphericity of the permutohedron]\label{thm:cosph}
For every $\sigma\in \Sn$,
\[
\sum_i \sigma(i) = L(n) = \frac{n(n-1)}{2},\qquad
\sum_i \sigma(i)^2 = R(n) = \frac{n(n-1)(2n-1)}{6}.
\]
Hence all $n!$ vertices of $\Pi_{n-1}$ lie on a common hyperplane and on a common sphere centred at the origin.
\end{theorem}

\begin{proof}
Both sums have the form $\sum_i f(\sigma(i))$; since $\sigma$ is a bijection of the index set, reindexing gives $\sum_i f(\sigma(i))=\sum_i f(i)$. The closed forms are Gauss's sum and the square-pyramidal sum, each by induction: $2L(n+1)=n(n-1)+2n=n(n+1)$ and $6R(n+1)=n(n-1)(2n-1)+6n^2=n(n+1)(2n+1)$.
\end{proof}

Theorem~\ref{thm:cosph} says no vertex is distinguished by length or by position along the all-ones direction. This is exactly the hypothesis under which a squared distance is equivalent to an inner product.

\section{The chordal representation}

\begin{theorem}[Chordal form]\label{thm:chordal}
$D(\sigma,\tau) = 2\bigl(R(n)-\langle\sigma,\tau\rangle\bigr)$ for all $\sigma,\tau\in \Sn$.
\end{theorem}

\begin{proof}
Expand $(\sigma(i)-\tau(i))^2=\sigma(i)^2+\tau(i)^2-2\sigma(i)\tau(i)$ and sum, applying Theorem~\ref{thm:cosph} to each square term.
\end{proof}

\begin{corollary}[Nonnegativity and separation]\label{cor:sep}
$D(\sigma,\tau)\ge 0$ with equality iff $\sigma=\tau$; and $D$ is symmetric.
\end{corollary}

\begin{proof}
$D$ is a sum of squares, vanishing iff every summand does, i.e.\ iff the rank vectors coincide.
\end{proof}

\begin{theorem}[Right invariance]\label{thm:rinv}
$D(\sigma\pi,\tau\pi)=D(\sigma,\tau)$ for all $\sigma,\tau,\pi\in \Sn$, and hence $D(\sigma,\tau)=D(\sigma\tau^{-1},\id)$. The same holds for $\langle\cdot,\cdot\rangle$.
\end{theorem}

\begin{proof}
$\rk(\sigma\pi)(i)=\sigma(\pi(i))$, so the summand at $i$ for $(\sigma\pi,\tau\pi)$ equals the summand at $\pi(i)$ for $(\sigma,\tau)$; sum over the bijection $\pi$. Take $\pi=\tau^{-1}$.
\end{proof}

Right invariance says the dial is relabelling-blind: it depends only on the relative permutation, so one may always compare against $\id$.

\begin{theorem}[Spearman is Pearson]\label{thm:pearson}
For $n\ge 2$ and all $\sigma,\tau\in \Sn$,
\[
12\Bigl(n\,\langle\sigma,\tau\rangle - L(n)^2\Bigr) = n^2(n^2-1)\,\rho(\sigma,\tau).
\]
\end{theorem}

\begin{proof}
The left-hand side is $12n^2$ times the covariance $\tfrac1n\langle\sigma,\tau\rangle-(L(n)/n)^2$ of the two rank vectors; the right-hand side is $\rho$ times $n^2$ times $12\Var(\rk)=n^2-1$. Concretely, substitute $\langle\sigma,\tau\rangle = R(n)-D/2$ from Theorem~\ref{thm:chordal} and $\rho=1-6D/(n^3-n)$, then eliminate $L(n)$ and $R(n)$ using $2L(n)=n(n-1)$ and $6R(n)=n(n-1)(2n-1)$; the identity reduces to a polynomial identity in $n$ and $D$.
\end{proof}

Since every rank vector has variance $(n^2-1)/12$, Theorem~\ref{thm:pearson} says $\rho$ \emph{is} the Pearson coefficient of the ranks: the constant $n^3-n$ is $12n$ times the rank variance, and there is nothing to choose.

\section{Extremes and the diameter}

\begin{lemma}[Inner-product ceiling]\label{lem:ipmax}
$\langle\sigma,\tau\rangle\le R(n)$, with equality iff $\sigma=\tau$.
\end{lemma}

\begin{proof}
Immediate from Theorem~\ref{thm:chordal} and Corollary~\ref{cor:sep}.
\end{proof}

Let $\rev\in\Sn$ denote the reversal, $\rev(i)=n-1-i$.

\begin{lemma}[Reflection identity]\label{lem:refl}
For any $\mu\in\Sn$, $\ \rk(\rev\cdot\mu)(i) = (n-1)-\rk\mu(i)$.
\end{lemma}

\begin{proof}
$(\rev\cdot\mu)(i)=\rev(\mu(i))=n-1-\mu(i)$.
\end{proof}

\begin{theorem}[Antipodality]\label{thm:anti}
For all $\sigma,\tau\in\Sn$, $\ \langle\sigma,\tau\rangle \ge (n-1)L(n)-R(n)$, with equality for $(\rev,\id)$. Hence $\rev$ minimises the inner product and maximises the distance.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:rinv} put $\mu=\sigma\tau^{-1}$, so $\langle\sigma,\tau\rangle=\langle\mu,\id\rangle$. By Lemma~\ref{lem:refl} and Theorem~\ref{thm:cosph},
\[
\langle \rev\cdot\mu,\ \id\rangle=\sum_i\bigl((n-1)-\rk\mu(i)\bigr)i=(n-1)L(n)-\langle\mu,\id\rangle .
\]
Apply Lemma~\ref{lem:ipmax} to the left side and rearrange. Taking $\mu=\id$ and using $\langle\id,\id\rangle=R(n)$ shows the bound is attained at $(\rev,\id)$.
\end{proof}

\begin{theorem}[Exact diameter]\label{thm:diam}
$\displaystyle\max_{\sigma,\tau\in\Sn} D(\sigma,\tau)=D(\rev,\id)=\frac{n(n^2-1)}{3}.$
\end{theorem}

\begin{proof}
Maximality combines Theorems~\ref{thm:anti} and~\ref{thm:chordal}. For the value, $D(\rev,\id)=4R(n)-2(n-1)L(n)$, and substituting $6R(n)=n(n-1)(2n-1)$, $2L(n)=n(n-1)$ gives $3D(\rev,\id)=2n(n-1)(2n-1)-3n(n-1)^2=n(n-1)(n+1)$.
\end{proof}

\begin{corollary}[Range and characterisation of $\pm1$]
For $n\ge2$, $-1\le\rho\le 1$; $\rho=1$ iff $\sigma=\tau$; and $\rho=-1$ iff $D(\sigma,\tau)=n(n^2-1)/3$, i.e.\ iff the two rankings are antipodal vertices.
\end{corollary}

\begin{proof}
The upper statement is Corollary~\ref{cor:sep}; the lower follows from Theorem~\ref{thm:diam}, which gives $6D/(n^3-n)\le 2$ with equality only at the diameter.
\end{proof}

\section{Quantisation and the rigidity gap}

\begin{theorem}[Parity invariant]\label{thm:parity}
$D(\sigma,\tau)$ is even for all $\sigma,\tau\in\Sn$.
\end{theorem}

\begin{proof}
Let $d_i=\sigma(i)-\tau(i)$. By Theorem~\ref{thm:cosph} the displacement vector sums to zero, $\sum_i d_i=0$. Hence
$\sum_i d_i^2=\sum_i (d_i^2-d_i)=\sum_i d_i(d_i-1)$,
and each term is a product of consecutive integers, hence even.
\end{proof}

Geometrically, the displacement lies in the root lattice $A_{n-1}$, on which the quadratic form is even.

\begin{theorem}[Separation]\label{thm:sep2}
If $\sigma\ne\tau$ then $D(\sigma,\tau)\ge 2$; in particular $D$ never takes an odd value.
\end{theorem}

\begin{proof}
$D\ge 0$, $D\ne 0$ by Corollary~\ref{cor:sep}, and $D$ even by Theorem~\ref{thm:parity}.
\end{proof}

\begin{theorem}[Rigidity gap]\label{thm:gap}
Let $n\ge2$ and $\sigma\ne\tau$. Then
\[
\rho(\sigma,\tau)\ \le\ 1-\frac{12}{n^3-n}.
\]
Equivalently, no attainable value of $\rho$ lies in the open interval $\bigl(1-\tfrac{12}{n^3-n},\,1\bigr)$, and any reading strictly above $1-\tfrac{12}{n^3-n}$ certifies $\sigma=\tau$ exactly.
\end{theorem}

\begin{proof}
Substitute $D\ge2$ (Theorem~\ref{thm:sep2}) into $\rho=1-6D/(n^3-n)$, using $n^3-n>0$.
\end{proof}

The gap width is $\tfrac12$ at $n=3$ (on the hexagon $\rho\in\{1,\tfrac12,-\tfrac12,-1\}$), $0.2$ at $n=4$, about $10^{-2}$ at $n=11$, and $1.2\times10^{-11}$ at $n=10^4$. For $n=3$ the six vertices realise exactly the squared distances $\{0,2,6,8\}$: every value even, $1$ absent, diameter $8=3(3^2-1)/3$. The value $4$ is absent too, so at $n=3$ parity is not the only obstruction; exhaustive enumeration for $4\le n\le 8$ shows this is an artefact of the smallest case, every even value in $[0,\,n(n^2-1)/3]$ being realised for $n\ge4$, so that from $n=4$ onwards parity describes the attainable spectrum exactly and the rigidity gap is attained.

\section{Exact unbiasedness: the centroid of the permutohedron}

\begin{lemma}[Position blindness]\label{lem:posblind}
For all $i,j$, $\ \sum_{\sigma\in\Sn}\sigma(i)=\sum_{\sigma\in\Sn}\sigma(j)$.
\end{lemma}

\begin{proof}
Right multiplication by the transposition $(i\,j)$ is a bijection of $\Sn$; reindexing, $\sum_\sigma \sigma(i)=\sum_\sigma(\sigma\cdot(i\,j))(i)=\sum_\sigma\sigma(j)$.
\end{proof}

Equivalently, the centroid of $\Pi_{n-1}$ is the barycentric point $\bigl(\tfrac{n-1}{2},\dots,\tfrac{n-1}{2}\bigr)$.

\begin{lemma}\label{lem:pin}
For every $i$, $\ n\sum_{\sigma\in\Sn}\sigma(i)=n!\,L(n)$.
\end{lemma}

\begin{proof}
Compute $\sum_j\sum_\sigma\sigma(j)$ two ways: exchanging the order and using Theorem~\ref{thm:cosph} gives $n!\,L(n)$; applying Lemma~\ref{lem:posblind} to each inner sum gives $n\sum_\sigma\sigma(i)$.
\end{proof}

\begin{lemma}\label{lem:meanip}
$n\sum_{\sigma\in\Sn}\langle\sigma,\id\rangle=n!\,L(n)^2$.
\end{lemma}

\begin{proof}
$\sum_\sigma\langle\sigma,\id\rangle=\sum_i i\sum_\sigma\sigma(i)$; multiply by $n$ and apply Lemma~\ref{lem:pin} termwise.
\end{proof}

\begin{theorem}[Exact first moment]\label{thm:moment}
$\displaystyle\sum_{\sigma\in\Sn}D(\sigma,\id)=\frac{n!\,(n^3-n)}{6}$, i.e.\ $\mathbb{E}\bigl[\textstyle\sum d^2\bigr]=(n^3-n)/6$ under the uniform ensemble.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:chordal}, $\sum_\sigma D(\sigma,\id)=2\bigl(n!\,R(n)-\sum_\sigma\langle\sigma,\id\rangle\bigr)$. Multiply by $n$, substitute Lemma~\ref{lem:meanip}, then eliminate $L(n),R(n)$ via $2L(n)=n(n-1)$ and $6R(n)=n(n-1)(2n-1)$ to obtain $6n\sum_\sigma D=n!\,n(n^3-n)$; cancel $n>0$.
\end{proof}

\begin{theorem}[The dial is exactly unbiased]\label{thm:null}
For $n\ge2$, $\displaystyle\sum_{\sigma\in\Sn}\rho(\sigma,\id)=0$.
\end{theorem}

\begin{proof}
$\sum_\sigma\rho=n!-\frac{6}{n^3-n}\sum_\sigma D$, and Theorem~\ref{thm:moment} makes the second term equal to $n!$.
\end{proof}

\begin{corollary}[Both signs occur]
For $n\ge2$ there exist $\sigma$ with $\rho(\sigma,\id)\le0$ and $\sigma'$ with $\rho(\sigma',\id)\ge0$.
\end{corollary}

\begin{proof}
If all values were strictly positive the sum would be positive, contradicting Theorem~\ref{thm:null}; and $\sigma'=\id$ gives $\rho=1$.
\end{proof}

For $n=3$: $\sum_\sigma D=24$, mean $4=(27-3)/6$, mean $\rho=0$. Theorem~\ref{thm:null} is stronger than the usual asymptotic statement: the normalisation $1-6\sum d^2/(n^3-n)$ is the unique affine rescaling that centres the statistic exactly at every finite $n$.

\section{The $\ell^1$ and combinatorial faces}

\begin{definition}[Footrule]
$F(\sigma,\tau):=\sum_i|\sigma(i)-\tau(i)|$, and $F(\sigma):=F(\sigma,\id)$.
\end{definition}

\begin{definition}[Inversions]
$\Invr(\sigma,i):=\{j: i<j,\ \sigma(j)<\sigma(i)\}$, $\ \Invl(\sigma,i):=\{j: j<i,\ \sigma(i)<\sigma(j)\}$, and $\inv(\sigma):=\sum_i|\Invr(\sigma,i)|$.
\end{definition}

\subsection{A right-invariant metric and a length function}

\begin{theorem}\label{thm:Fmetric}
$F$ is a metric on $\Sn$: nonnegative, symmetric, definite, and satisfying the triangle inequality. It is right-invariant: $F(\sigma\pi,\tau\pi)=F(\sigma,\tau)$.
\end{theorem}

\begin{proof}
Nonnegativity, symmetry and definiteness are termwise. The triangle inequality is $|a-c|\le|a-b|+|b-c|$ summed. Right invariance is the reindexing argument of Theorem~\ref{thm:rinv}.
\end{proof}

\begin{theorem}[Length function]\label{thm:Fsub}
$F(\sigma\tau)\le F(\sigma)+F(\tau)$.
\end{theorem}

\begin{proof}
By right invariance $F(\sigma\tau,\tau)=F(\sigma)$; the triangle inequality through the midpoint $\tau$ gives $F(\sigma\tau)\le F(\sigma\tau,\tau)+F(\tau)$.
\end{proof}

\begin{theorem}[Cost of a transposition]\label{thm:Fswap}
$F\bigl((a\,b)\bigr)=2|a-b|$.
\end{theorem}

\begin{proof}
The transposition fixes every index outside $\{a,b\}$, so all other summands vanish; the two surviving terms are each $|a-b|$. For $a=b$ both sides are $0$.
\end{proof}

\subsection{Equivalence of the $\ell^1$ and $\ell^2$ readings}

\begin{theorem}[Two-sided comparison]\label{thm:FD}
$F(\sigma,\tau)\ \le\ D(\sigma,\tau)\ \le\ (n-1)\,F(\sigma,\tau)$.
\end{theorem}

\begin{proof}
Left: $|x|\le x^2$ for integers ($x=0$ trivially; else $|x|\ge1$), summed termwise. Right: each displacement satisfies $|\sigma(i)-\tau(i)|\le n-1$, so $(\sigma(i)-\tau(i))^2\le(n-1)|\sigma(i)-\tau(i)|$, summed termwise.
\end{proof}

\begin{theorem}[Cauchy--Schwarz refinement]\label{thm:CS}
$F(\sigma,\tau)^2\le n\,D(\sigma,\tau)$.
\end{theorem}

\begin{proof}
Cauchy--Schwarz applied to $\sum_i |d_i|\cdot 1$ over $n$ terms.
\end{proof}

\subsection{The Diaconis--Graham upper bound}

\begin{lemma}[Rightward displacement is charged to inversions]\label{lem:right}
$\sigma(i)\le i+|\Invr(\sigma,i)|$ for all $\sigma$ and $i$.
\end{lemma}

\begin{proof}
Let $S=\{j:\sigma(j)<\sigma(i)\}$; since $\sigma$ is a bijection onto $\{0,\dots,n-1\}$, $|S|=\sigma(i)$. Split $S$ by position: the part with $j>i$ is exactly $\Invr(\sigma,i)$, and the part with $j\le i$ excludes $j=i$, hence lies in $\{0,\dots,i-1\}$ and has at most $i$ elements.
\end{proof}

\begin{lemma}[Leftward displacement, dually]\label{lem:left}
$i\le \sigma(i)+|\Invl(\sigma,i)|$ for all $\sigma$ and $i$.
\end{lemma}

\begin{proof}
Let $T=\{j:\sigma(i)<\sigma(j)\}$, so $|T|=n-1-\sigma(i)$. Its part with $j<i$ is $\Invl(\sigma,i)$; its part with $j>i$ has at most $n-1-i$ elements. Hence $n-1-\sigma(i)\le|\Invl(\sigma,i)|+(n-1-i)$.
\end{proof}

\begin{lemma}[Double counting]\label{lem:dc}
$\inv(\sigma)=\sum_i|\Invl(\sigma,i)|$.
\end{lemma}

\begin{proof}
Both sides count the inverted pairs $\{(i,j):i<j,\ \sigma(j)<\sigma(i)\}$, grouped by left and by right endpoint respectively; exchanging the order of summation converts one grouping into the other.
\end{proof}

\begin{theorem}[Diaconis--Graham upper bound]\label{thm:DG}
$F(\sigma)\ \le\ 2\,\inv(\sigma)$ for all $\sigma\in\Sn$.
\end{theorem}

\begin{proof}
Lemmas~\ref{lem:right} and~\ref{lem:left} give $-|\Invl(\sigma,i)|\le\sigma(i)-i\le|\Invr(\sigma,i)|$, hence $|\sigma(i)-i|\le|\Invr(\sigma,i)|+|\Invl(\sigma,i)|$ since both terms are nonnegative. Summing over $i$ and applying Lemma~\ref{lem:dc} to the second group yields $F(\sigma)\le\inv(\sigma)+\inv(\sigma)$.
\end{proof}

\begin{proposition}[Sharpness]\label{prop:sharp}
The constant $2$ cannot be reduced: for the adjacent transposition $(0\,1)$, $F=2$ and $\inv=1$. It is not always tight: for $(0\,2)$ in $S_3$, $F=4<6=2\inv$.
\end{proposition}

\begin{corollary}[Euclidean bound from combinatorial data]\label{cor:Dinv}
$D(\sigma,\id)\le 2(n-1)\inv(\sigma)$.
\end{corollary}

\begin{proof}
Chain Theorem~\ref{thm:FD} (right half) with Theorem~\ref{thm:DG}.
\end{proof}

\begin{corollary}[Positivity transfer]
For $\sigma\ne\id$: $F(\sigma)>0$ and $\inv(\sigma)>0$.
\end{corollary}

\begin{proof}
$F(\sigma)>0$ by definiteness; Theorem~\ref{thm:DG} then forces $\inv(\sigma)>0$.
\end{proof}

Theorems~\ref{thm:FD}, \ref{thm:CS} and~\ref{thm:DG} together show that total travel ($\ell^1$), squared travel ($\ell^2$) and pairwise disorder are equivalent up to factors depending only on $n$. Operationally: a violation of an acceptance band in one of these metrics is a violation in all three, so no reparametrisation of the disagreement measure rescues a failing operating point.

\section{The block ceiling: why thresholding caps the correlation}

A threshold does not perturb a ranking; it destroys one, replacing a permutation-valued object by a two-block indicator.

\begin{definition}[Block statistics]\label{def:block}
Let $B\subseteq\{0,\dots,n-1\}$ with $|B|=m$ be the flagged set $\{i: T_i>u\}$. For $\sigma\in\Sn$ set
\[
\Sigma_B(\sigma):=\sum_{i\in B}\sigma(i),\qquad C_B(\sigma):=n\,\Sigma_B(\sigma)-m\,L(n),
\]
and define the squared point-biserial correlation between $\mathbf 1_B$ and $\rk\sigma$ by
\[
r^2(\sigma,B):=\frac{12\,C_B(\sigma)^2}{n^2\,m\,(n-m)\,(n^2-1)} .
\]
\end{definition}

This is the standard definition: $C_B(\sigma)/n^2=\Cov(\mathbf 1_B,\rk\sigma)$, $\Var(\mathbf 1_B)=m(n-m)/n^2$ and $\Var(\rk\sigma)=(n^2-1)/12$.

\begin{theorem}[Extremal block sums]\label{thm:blocksum}
For every $\sigma\in\Sn$ and every $B$ with $|B|=m$,
\[
\frac{m(m-1)}{2}\ \le\ \Sigma_B(\sigma)\ \le\ \frac{m(2n-m-1)}{2},
\]
and both bounds are attained.
\end{theorem}

\begin{proof}
The multiset $\{\sigma(i):i\in B\}$ consists of $m$ \emph{distinct} integers in $\{0,\dots,n-1\}$. The smallest sum of $m$ distinct nonnegative integers is $0+1+\cdots+(m-1)$; the largest sum of $m$ distinct integers each at most $n-1$ is $(n-1)+\cdots+(n-m)$. Attainment: take $B$ to be the bottom, resp.\ top, $m$ positions under the identity ranking.
\end{proof}

\begin{theorem}[Covariance bound]\label{thm:cov}
$|2\,C_B(\sigma)|\le n\,m\,(n-m)$, equivalently $|\Cov(\mathbf 1_B,\rk\sigma)|\le \tfrac12 n\,p(1-p)$ with $p=m/n$.
\end{theorem}

\begin{proof}
Using $2L(n)=n(n-1)$, the upper half of Theorem~\ref{thm:blocksum} gives $2C_B\le n\,m(2n-m-1)-m\,n(n-1)=n\,m\,(n-m)$, and the lower half gives $2C_B\ge n\,m(m-1)-m\,n(n-1)=-n\,m\,(n-m)$.
\end{proof}

\begin{theorem}[Block ceiling]\label{thm:ceiling}
Let $0<m<n$. Then for every $\sigma\in\Sn$ and every $B$ with $|B|=m$,
\[
r^2(\sigma,B)\ \le\ \frac{3\,m\,(n-m)}{n^2-1}\ =\ \frac{3\,p(1-p)\,n^2}{n^2-1}\ \approx\ 3p(1-p).
\]
\end{theorem}

\begin{proof}
Squaring Theorem~\ref{thm:cov} gives $4C_B^2\le n^2m^2(n-m)^2$; substituting into Definition~\ref{def:block},
\[
r^2=\frac{12C_B^2}{n^2m(n-m)(n^2-1)}\le \frac{3\,n^2m^2(n-m)^2}{n^2m(n-m)(n^2-1)}=\frac{3m(n-m)}{n^2-1}.\qedhere
\]
\end{proof}

The bound is sharp in the sense that its input inequality is attained: at $n=4$, $m=2$, the top block $\{2,3\}$ under the identity ranking realises $2\Sigma_B=10=m(2n-m-1)$, and the ceiling reads $3\cdot2\cdot2/15=4/5$.

\begin{corollary}[Deployment criterion]\label{cor:deploy}
Let $0<m<n$ and let $c>0$ be a target correlation. If $3m(n-m)<c^2(n^2-1)$, then $r^2(\sigma,B)<c^2$ for every statistic and every ranking: the target is unreachable in principle.
\end{corollary}

\subsection{The empirical regime}

Take $n=100$ strata with a $10\%$ flag rate, $m=10$. Theorem~\ref{thm:ceiling} gives the exact bound
\[
r^2\le\frac{3\cdot10\cdot90}{100^2-1}=\frac{2700}{9999}\approx0.27003,\qquad |r|\le 0.5196 .
\]
The pre-registered band floor $0.71$ requires $r^2\ge0.5041$, i.e.\ $c^2(n^2-1)=5040.5>2700$, so Corollary~\ref{cor:deploy} applies and the band is structurally unreachable.

